{"l":7791,"g":8,"b":3,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ydmyg' på engelsk?","o":["humid","hostile","noble","humble"],"a":"humble","r":"'Humble' = ydmyg. Fugtig hedder 'humid'."},
